268:   // Utility functions for byte order conversion
269:   template <typename T>
270:   inline T swap(T val) {
271:     if constexpr (std::is_same_v<T, Rational> || std::is_same_v<T, SRational>) {
272:       return { std::byteswap(val.numerator), std::byteswap(val.denominator) };
273:     } else if constexpr (std::is_same_v<T, float>) {
274:       uint32_t u32;
275:       std::memcpy(&u32, &val, sizeof(u32));
276:       u32 = std::byteswap(u32);
277:       std::memcpy(&val, &u32, sizeof(val));
278:       return val;
279:     } else if constexpr (std::is_same_v<T, double>) {
280:       uint64_t u64;
281:       std::memcpy(&u64, &val, sizeof(u64));
282:       u64 = std::byteswap(u64);
283:       std::memcpy(&val, &u64, sizeof(val));
284:       return val;
285:     } else if constexpr (std::is_same_v<T, Tag>) {
286:       const auto value = static_cast<std::underlying_type_t<Tag>>(val);
287:       return static_cast<Tag>(std::byteswap(value));
288:     } else if constexpr (std::is_same_v<T, Type>) {
289:       const auto value = static_cast<std::underlying_type_t<Type>>(val);
290:       return static_cast<Type>(std::byteswap(value));
291:     } else if constexpr (sizeof(T) > 1) {
292:       return std::byteswap(val);
293:     }
294:     else {
295:       return val; // No swap needed single byte
296:     }
297:   }
