739:   void load(std::istream& stream, LoadCallback&& callback, const LoadParams& params = {}) {
740:     // Read the TIFF image from the stream
741:     TiffImage image = TiffImage::read(stream);
742:     const auto& header = image.header();
743: 
744:     if (params.ifdIndex && params.ifdIndex.value() >= image.ifds().size()) {
745:       throw std::runtime_error("Requested IFD index is out of bounds");
746:     }
747: 
748:     for (size_t i = 0; i < image.ifds().size(); ++i) {
749:       if (!params.ifdIndex || params.ifdIndex.value() == i) {
750:         // If a specific IFD index is requested, only process that IFD
751:         // Otherwise, process all IFDs
752:         const auto& ifd = image.ifds()[i];
753:         if (ifd.entries().contains(Tag::StripOffsets)) {
754:           // image contains strip offsets
755:           callback(header, ifd, TiffImage::readImageStrips(stream, ifd));
756:         } else if (ifd.entries().contains(Tag::TileByteCounts)) {
757:           // image contains tile byte counts
758:           callback(header, ifd, TiffImage::readImageTiles(stream, ifd));
759:         } else {
760:           throw std::runtime_error("Unsupported IFD format");
761:         }
762:       }
763:     }
