381:           // if seeking fails, we check if we tried to seek beyond the end of
382:           // the stream and if so, we pad the stream with zeros until we reach
383:           // the desired position
384:           stream.clear(); // Clear any error flags
385:           stream.seekp(0, std::ios_base::end);
386:           while (stream && stream.tellp() < p) {
387:             stream.put(0); // Pad with zeros if necessary
388:           }
389:           assert(stream.tellp() == p && "SeekGuard did not reach the desired position");
390:         }
391:       }
392:       ~SeekGuard() {
393:         stream.seekp(oldPos);
394:       }
395:     } seekGuard(stream, pos);
396:     if (!stream || stream.tellp() != pos) {
397:       throw std::runtime_error("Failed to seek to position in stream");
398:     }
399:     stream.write(reinterpret_cast<const char*>(buffer), size);
400:     return stream;
401:   }
402: 
403:   class TiffImage {
404:   public:
405: 
406:     // Header class
407:     // ============
408:     // A TIFF file begins with an 8-byte image file header:
409:     // - Bytes 0-1: The byte order used within the file. Legal values are:
410:     //   - “II” (4949.H)
411:     //   - “MM” (4D4D.H)
412:     //   In the “II” format, byte order is always from the least significant
413:     //   byte to the most significant byte, for both 16-bit and 32-bit integers
414:     //   This is called little-endian byte order. In the “MM” format, byte order
415:     //   is always from most significant to least significant, for both 16-bit
416:     //   and 32-bit integers. This is called big-endian byte order.
417:     // - Bytes 2-3 An arbitrary but carefully chosen number (42) that further
418:     //   identifies the file as a TIFF file. The byte order depends on the value
419:     //   of Bytes 0-1.
420:     // - Bytes 4-7 The offset (in bytes) of the first IFD. The directory may be
421:     //   at any location in the file after the header but must begin on a word
422:     //   boundary.
423:     class Header {
424:       std::endian byteOrder_;
425:       uint32_t firstIFDOffset_;
426:     public:
427:       std::endian byteOrder() const { return byteOrder_; }
428: 
429:       bool equalsHostByteOrder() const {
430:         return std::endian::native == byteOrder_;
431:       }
432: 
433:       uint32_t firstIFDOffset() const { return firstIFDOffset_; }
434: 
435:       static Header read(std::istream& stream) {
436:         Header header;
437: 
438:         // Byte order
439:         uint16_t byteOrder = readValue<uint16_t>(stream); // 0x4949 for "II", 0x4D4D for "MM"
440:         if (byteOrder != 0x4949 && byteOrder != 0x4D4D) {
441:           throw std::runtime_error("Invalid byte order in TIFF header");
442:         }
443:         header.byteOrder_ =
444:           (byteOrder == 0x4949) ? std::endian::little : std::endian::big;
445: 
446:         // Swap byte order if necessary
447:         const bool mustSwap = !header.equalsHostByteOrder();
448: 
449:         // Magic number
450:         uint16_t magicNumber = readValue<uint16_t>(stream, mustSwap);
451:         if (magicNumber != 42) {
452:           throw std::runtime_error("Invalid magic number in TIFF header");
453:         }
454: 
455:         // First IFD offset
456:         uint32_t firstIFDOffset = readValue<uint32_t>(stream, mustSwap);
457:         if (firstIFDOffset < 8) { // Minimum size of TIFF header
458:           throw std::runtime_error("Invalid first IFD offset in TIFF header");
459:         }
460:         header.firstIFDOffset_ = firstIFDOffset;
461: 
462:         return header;
463:       }
464:     };
465: 
466:     // IFD class
467:     // =========
468:     // An Image File Directory (IFD) consists of a 2-byte count of the
469:     // number of directory entries (i.e., the number of fields), followed
470:     // by a sequence of 12-byte field entries, followed by a 4-byte offset
471:     // of the next IFD (or 0 if none).
472:     class IFD {
473:     public:
474: 
475:       // Entry class
476:       // ===========
477:       // Each IFD entry is a 12-byte structure that describes a field in the
478:       // image. The structure is as follows:
479:       // - Bytes 0-1: The Tag that identifies the field.
480:       // - Bytes 2-3: The field Type.
481:       // - Bytes 4-7: The number of values (Count) of the indicated Type.
482:       // - Bytes 8-11: The Value is expected to begin on a word boundary; the
483:       //   corresponding Value Offset will thus be an even number. This file
484:       //   offset may point anywhere in the file, even after the image data.
485:       //   The value of the field, or an offset to the value if it is too large
486:       //   to fit in 4 bytes.
487:       //
488:       // Sort Order
489:       // ----------
490:       // The entries in an IFD must be sorted in ascending order by Tag.
491:       // The Values to which directory entries point need not be in any
492:       // particular order in the file.
493:       //
494:       // Value/Offset
495:       // ------------
496:       // To save time and space the Value Offset contains the Value instead of
497:       // pointing to the Value if and only if the Value fits into 4 bytes. If
498:       // the Value is shorter than 4 bytes, it is left-justified within the
499:       // 4-byte Value Offset, i.e., stored in the lower-numbered bytes. Whether
500:       // the Value fits within 4 bytes is determined by the Type and Count of
501:       // the field.
502:       //
503:       // Count
504:       // -----
505:       // Count (called Length in previous versions of the specification) is the
506:       // number of values. Note that Count is not the total number of bytes.
507:       // For example, a single 16-bit word (SHORT) has a Count of 1; not 2.
508:       // The value of the Count part of an ASCII field entry includes the NUL.
509:       // If padding is necessary, the Count does not include the pad byte.
510:       //
511:       // Types
512:       // -----
513:       // The field types and their sizes are defined in the `Type` enum.
514:       class Entry {
515:       public:
516:         Tag tag() const { return tag_; }
517:         Type type() const { return type_; }
518:         uint32_t count() const { return count_; }
519:         const std::byte* values() const { return values_.data(); }
520: 
521:         template <typename T>
522:         std::span<const T> values() const {
523:           if (sizeof(T) != TiffCraft::typeBytes(type_)) {
524:             throw std::runtime_error("Invalid type size for values span");
525:           }
526:           return std::span<const T>(reinterpret_cast<const T*>(values_.data()), count());
527:         }
528: 
529:         uint32_t bytes() const { return count() * TiffCraft::typeBytes(type_); }
530: 
531:         static Entry read(std::istream& stream, bool mustSwap = false) {
532:           Entry entry;
533:           entry.tag_ = static_cast<Tag>(readValue<uint16_t>(stream, mustSwap));
534:           entry.type_ = static_cast<Type>(readValue<uint16_t>(stream, mustSwap));
535:           entry.count_ = readValue<uint32_t>(stream, mustSwap);
536: 
537:           // Read the value
538:           const uint32_t valueSize = entry.bytes();
539:           entry.values_.resize(valueSize);
540:           if (valueSize <= sizeof(uint32_t)) {
541:             // Value fits in 4 bytes, read directly
542:             const uint32_t value = readValue<uint32_t>(stream);
543:             std::memcpy(entry.values_.data(), &value, valueSize);
544:           }
545:           else {
546:             // Value is too large, read as an offset
547:             uint32_t valueOffset = readValue<uint32_t>(stream, mustSwap);
548:             if (valueOffset < 8 || valueOffset % 2 != 0) {
549:               throw std::runtime_error("Invalid value offset in TIFF entry");
550:             }
551:             readAt(stream, valueOffset, entry.values_.data(), valueSize);
552:           }
553: 
554:           // Swap values after reading them to treat them as an array, instead
555:           // of a single `uint32_t`. This is because the values may not be a
556:           // single `uint32_t` but rather a sequence of smaller types (e.g.,
557:           // uint16_t, uint8_t).
558:           // This is necessary to ensure that the values are correctly
559:           // interpreted according to their type.
560:           if (mustSwap) {
561:             swapArray(entry.values_.data(), entry.type_, entry.count_);
562:           }
563: 
564:           if (entry.type_ == Type::ASCII) {
565:             // Ensure the last byte is NUL for ASCII type
566:             if (entry.values_[valueSize - 1] != std::byte{0}) {
567:               throw std::runtime_error("ASCII value must end with NUL byte");
568:             }
569:           }
570: 
571:           return entry;
572:         }
573: 
574:         bool operator==(const Entry& other) const {
575:           return tag_ == other.tag_ &&
576:                  type_ == other.type_ &&
577:                  count_ == other.count_ &&
578:                  values_ == other.values_;
579:         }
580: 
581:       private:
582:         Tag tag_;                       // Tag identifying the field
583:         Type type_;                     // Type of the field
584:         uint32_t count_;                // Number of values
585:         std::vector<std::byte> values_; // Pointer to the value data
586:       };
587: 
588:       const std::map<Tag, Entry>& entries() const { return entries_; }
589: 
590:       const Entry& getEntry(Tag tag,
591:         std::string errorMessage = "Entry not found") const {
592:         auto it = entries_.find(tag);
593:         if (it == entries_.end()) {
594:           throw std::runtime_error(errorMessage);
595:         }
596:         return it->second;
597:       }
598: 
599:       static IFD read(std::istream& stream, bool mustSwap = false) {
600:         IFD ifd;
601: 
602:         // Read the number of entries
603:         uint16_t entryCount = readValue<uint16_t>(stream, mustSwap);
604: 
605:         // Read each entry
606:         Tag lastTag = Tag::Null;
607:         for (uint16_t i = 0; i < entryCount; ++i) {
608:           Entry entry = Entry::read(stream, mustSwap);
609:           ifd.entries_[entry.tag()] = std::move(entry);
610:           if (entry.tag() <= lastTag) {
611:             throw std::runtime_error("Entries must be sorted by tag in ascending order");
612:           }
613:           lastTag = entry.tag();
614:         }
615: 
616:         return ifd;
617:       }
618: 
619:       private:
620:         std::map<Tag, Entry> entries_; // Map of directory entries
621:     };
622: 
623:     using ImageData = std::vector<std::vector<std::byte>>;
624: 
625:     const Header& header() const { return header_; }
626:     const std::vector<IFD>& ifds() const { return ifds_; }
627: 
628:     std::istream& stream() const {
629:       if (!stream_) {
630:         throw std::runtime_error("Stream is not set for this TIFF image");
631:       }
632:       return *stream_;
633:     }
634: 
635:     static TiffImage read(const std::string& filename) {
636:       std::ifstream file(filename, std::ios::binary);
637:       if (!file) {
638:         throw std::runtime_error("Failed to open TIFF file: " + filename);
639:       }
640:       auto image = read(file);
641:       image.stream_ = std::make_unique<std::ifstream>(std::move(file));
642:       return image;
643:     }
644: 
645:     static TiffImage read(std::istream& stream) {
646:       TiffImage image;
647: 
648:       // Read and parse the header
649:       image.header_ = Header::read(stream);
650: 
651:       // Read the IFDs
652:       const bool mustSwap = !image.header_.equalsHostByteOrder();
653:       uint32_t offset = image.header_.firstIFDOffset();
654:       while (offset > 0) {
655:         // Seek to the IFD offset
656:         stream.seekg(offset);
657:         if (stream.fail()) {
658:           throw std::runtime_error("Failed to seek to IFD offset");
659:         }
660: 
661:         // Read the IFD
662:         TiffImage::IFD ifd = TiffImage::IFD::read(stream, mustSwap);
663:         image.ifds_.push_back(std::move(ifd));
664: 
665:         // Read the next IFD offset
666:         offset = readValue<uint32_t>(stream, mustSwap);
667:       }
668: 
669:       return image;
670:     }
671: 
672:     static ImageData readImageStrips(std::istream& stream, const IFD& ifd) {
673:       const auto& entries = ifd.entries();
674:       std::vector<uint32_t> stripOffsets, stripByteCounts;
675:       { //copy offsets
676:         const auto& entry = ifd.getEntry(Tag::StripOffsets, "StripOffsets entry not found in IFD");
677:         copyVector<uint32_t>(entry.type(), entry.values(), entry.count(), stripOffsets);
678:       }
679:       { //copy byte counts
680:         const auto& entry = ifd.getEntry(Tag::StripByteCounts, "StripByteCounts entry not found in IFD");
681:         copyVector<uint32_t>(entry.type(), entry.values(), entry.count(), stripByteCounts);
682:       }
683:       if (stripOffsets.size() != stripByteCounts.size()) {
684:         throw std::runtime_error("Mismatch between number of StripOffsets and StripByteCounts");
685:       }
686:       ImageData imageData;
687:       for (size_t i = 0; i < stripOffsets.size(); ++i) {
688:         const uint32_t offset = stripOffsets[i];
689:         const uint32_t byteCount = stripByteCounts[i];
690:         if (offset < 8 || byteCount == 0) {
691:           throw std::runtime_error("Invalid strip offset or byte count");
692:         }
693:         imageData.emplace_back(byteCount);
694:         readAt(stream, offset, imageData.back().data(), byteCount);
695:       }
696:       return imageData;
697:     }
698: 
699:     static ImageData readImageTiles(std::istream& stream, const IFD& ifd) {
700:       const auto& entries = ifd.entries();
701:       std::vector<uint32_t> tileOffsets, tileByteCounts;
702:       { //copy offsets
703:         const auto& entry = ifd.getEntry(Tag::TileOffsets, "TileOffsets entry not found in IFD");
704:         copyVector<uint32_t>(entry.type(), entry.values(), entry.count(), tileOffsets);
705:       }
706:       { //copy byte counts
707:         const auto& entry = ifd.getEntry(Tag::TileByteCounts, "TileByteCounts entry not found in IFD");
708:         copyVector<uint32_t>(entry.type(), entry.values(), entry.count(), tileByteCounts);
709:       }
710:       if (tileOffsets.size() != tileByteCounts.size()) {
711:         throw std::runtime_error("Mismatch between number of TileOffsets and TileByteCounts");
712:       }
713:       ImageData imageData;
714:       for (size_t i = 0; i < tileOffsets.size(); ++i) {
715:         const uint32_t offset = tileOffsets[i];
716:         const uint32_t byteCount = tileByteCounts[i];
717:         if (offset < 8 || byteCount == 0) {
718:           throw std::runtime_error("Invalid tile offset or byte count");
719:         }
720:         imageData.emplace_back(byteCount);
721:         readAt(stream, offset, imageData.back().data(), byteCount);
722:       }
723:       return imageData;
724:     }
725: 
726:     private:
727:       Header header_;
728:       std::vector<IFD> ifds_; // List of IFDs in the TIFF image
729:       std::unique_ptr<std::istream> stream_;
730:   };
731: 
732:   struct LoadParams {
733:     std::optional<uint16_t> ifdIndex; // Optional IFD index to load
734:   };
735: 
736:   using LoadCallback = std::function<void(
737:     const TiffImage::Header&, const TiffImage::IFD&, TiffImage::ImageData)>;
738: 
739:   void load(std::istream& stream, LoadCallback&& callback, const LoadParams& params = {}) {
740:     // Read the TIFF image from the stream
741:     TiffImage image = TiffImage::read(stream);
742:     const auto& header = image.header();
743: 
744:     if (params.ifdIndex && params.ifdIndex.value() >= image.ifds().size()) {
745:       throw std::runtime_error("Requested IFD index is out of bounds");
746:     }
747: 
748:     for (size_t i = 0; i < image.ifds().size(); ++i) {
749:       if (!params.ifdIndex || params.ifdIndex.value() == i) {
750:         // If a specific IFD index is requested, only process that IFD
751:         // Otherwise, process all IFDs
752:         const auto& ifd = image.ifds()[i];
753:         if (ifd.entries().contains(Tag::StripOffsets)) {
754:           // image contains strip offsets
755:           callback(header, ifd, TiffImage::readImageStrips(stream, ifd));
756:         } else if (ifd.entries().contains(Tag::TileByteCounts)) {
757:           // image contains tile byte counts
758:           callback(header, ifd, TiffImage::readImageTiles(stream, ifd));
759:         } else {
760:           throw std::runtime_error("Unsupported IFD format");
761:         }
762:       }
763:     }
764:   }
765: 
766:   void load(const std::string& filename, LoadCallback&& callback, const LoadParams& params = {}) {
767:     std::ifstream file(filename, std::ios::binary);
768:     if (!file) {
769:       throw std::runtime_error("Failed to open TIFF file: " + std::string(filename));
770:     }
771:     load(file, std::move(callback), params);
772:   }
773: 
