63:   struct Image
64:   {
65:     int width = 0;          // Image width
66:     int height = 0;         // Image height
67:     int channels = 0;       // Number of color channels (e.g., 3 for RGB, 4 for RGBA)
68:     int rowStride = 0;      // Bytes per row
69:     int colStride = 0;      // Bytes per pixel
70:     int chanStride = 0;     // Bytes per channel
71:     int bitDepth = 0;       // Bits per channel
72:     std::vector<std::byte> data;  // Raw pixel data
73: 
74:     template <typename T, int N = 1>
75:     static Image make(int width, int height, bool isPlanar = false)
76:     {
77:       constexpr int sT = static_cast<int>(sizeof(T));
78:       if (isPlanar) {
79:         return Image{
80:           width, height, N,                     // width, height, channels
81:           width * sT,  sT, width * height * sT, // strides: row, column, channel
82:           sT * 8,                               // bit depth
83:           std::vector<std::byte>(width * height * N * sT) };
84:       }
85:       return Image{
86:         width, height, N,             // width, height, channels
87:         width * N * sT,  N * sT, sT,  // strides: row, column, channel
88:         sT * 8,                       // bit depth
89:         std::vector<std::byte>(width * height * N * sT) };
90:     }
