337:     template <typename SrcType, typename DstType, typename UnaryOp>
338:     void copyRectangles(
339:       const TiffImage::ImageData& imageData,  // source pixel data
340:       const RectInfo& rectInfo,               // source rectangle info
341:       size_t channels,                        // source image channels
342:       size_t planes,                          // source image planes
343:       bool equalsHostByteOrder,               // source data byte order
344:       UnaryOp&& op)
345:     {
346:       const int imageWidth = image_.width;
347:       const int imageHeight = image_.height;
348: 
349:       const int rectAcross = (imageWidth + (rectInfo.width - 1)) / rectInfo.width;
350:       const int rectDown = (imageHeight + (rectInfo.height - 1)) / rectInfo.height;
351:       const int rectsInPlane = rectAcross * rectDown;
352: 
353:       const int rectsInImage = rectAcross * rectDown * planes;
354:       if (rectsInImage != imageData.size()) {
355:         throw std::runtime_error("Rectangle count mismatch");
356:       }
357: 
358:       for (int plane = 0; plane < planes; ++plane) {
359:         for (int rectY = 0; rectY < rectDown; ++rectY) {
360:           for (int rectX = 0; rectX < rectAcross; ++rectX) {
361:             const auto& rectData = imageData[plane * rectsInPlane + rectY * rectAcross + rectX];
362:             auto currRectInfo = rectInfo;
363:             currRectInfo.width = std::min(rectInfo.width, imageWidth - rectX * rectInfo.width);
364:             currRectInfo.height = std::min(rectInfo.height, imageHeight - rectY * rectInfo.height);
365:             copyRectangle<SrcType, DstType, UnaryOp>(
366:               rectData,                    // source pixel data
367:               currRectInfo,                // source rectangle info
368:               channels,                    // source image channels
369:               equalsHostByteOrder,         // source data byte order
370:               plane,                       // destination plane
371:               rectX * rectInfo.width,      // destination column
372:               rectY * rectInfo.height,     // destination row
373:               std::forward<UnaryOp>(op));
374:           }
375:         }
376:       }
377:     }
378: 
379:     template <typename SrcType, typename DstType, typename UnaryOp>
380:     void copyRectangle(
381:       const std::vector<std::byte>& rectData, // source pixel data
382:       const RectInfo& rectInfo,               // source rectangle info
383:       size_t channels,                        // source image channels
384:       bool equalsHostByteOrder,               // source data byte order
385:       size_t dstPlane,                        // destination plane
386:       size_t dstX,                            // destination column
387:       size_t dstY,                            // destination row
388:       UnaryOp&& op)
389:     {
390:       constexpr size_t bitsPerSrcPixel = 8 * sizeof(SrcType);
391:       const auto* src = rectData.data();
392:       const auto* srcEnd = rectData.data() + rectData.size();
393: 
394:       size_t countAvail = 0;
395:       SrcType bitsAvail = 0;
396: 
397:       using ValueType = std::invoke_result_t<UnaryOp, DstType>;
398: 
399:       const size_t dstRowStride = image_.rowStride / sizeof(ValueType);
400:       const size_t dstColStride = image_.colStride / sizeof(ValueType);
401:       const size_t dstChanStride = image_.chanStride / sizeof(ValueType);
402:       const size_t dstPlaneStride = dstRowStride * image_.height;
403:       auto* dst = image_.dataPtr<ValueType>()
404:         + dstPlane * dstPlaneStride
405:         + dstY * dstRowStride
406:         + dstX * dstColStride;
407: 
408:       const auto* srcRow = src;
409:       auto* dstRow = dst;
410: 
411:       auto loop = [&](auto processor) {
412:         for (int row = 0; row < rectInfo.height; ++row) {
413:           if (src >= srcEnd) {
414:             // We've reached the end of the source tile
415:             throw std::runtime_error("Unexpected end of source tile");
416:           }
417:           srcRow = src;
418:           dstRow = dst;
419:           for (int col = 0; col < rectInfo.width; ++col) {
420:             auto* dstChan = dstRow;
421:             for (int chan = 0; chan < channels; ++chan) {
422:               DstType value = processor();
423:               *dstChan = std::invoke(op, value);
424:               dstChan += dstChanStride;
425:             }
426:             dstRow += dstColStride;
427:           }
428:           src += rectInfo.stride;
429:           dst += dstRowStride;
430:           // flush partial words when the row is complete
431:           if (countAvail > 0) {
432:             countAvail = 0;
433:             bitsAvail = 0;
434:           }
435:         }
436:       };
437: 
438:       auto process_word = [&]() -> DstType {
439:         DstType value = *reinterpret_cast<const SrcType*>(&(*srcRow));
440:         srcRow += sizeof(SrcType);
441:         if (!equalsHostByteOrder) {
442:           value = swap(value);
443:         }
444:         return value;
445:       };
446: 
447:       auto process_bits = [&]() -> DstType {
448:         size_t count = 0;
449:         DstType value = 0;
450:         while (count < rectInfo.bitsPerSample) {
451:           // make sure we have some bits available
452:           if (countAvail == 0) {
453:             bitsAvail = *reinterpret_cast<const SrcType*>(&(*srcRow));
454:             srcRow += sizeof(SrcType);
455:             if (!equalsHostByteOrder) {
456:               bitsAvail = swap(bitsAvail);
457:             }
458:             countAvail = bitsPerSrcPixel;
459:           }
460:           // consume available bits
461:           const size_t n = std::min(rectInfo.bitsPerSample - count, countAvail);
462:           value <<= n;
463:           value |= (bitsAvail >> (bitsPerSrcPixel - n));
464:           count += n;
465:           // update available bits
466:           countAvail -= n;
467:           bitsAvail <<= n;
468:         }
469:         assert(count == rectInfo.bitsPerSample);
470:         return value;
471:       };
472: 
473:       if (rectInfo.bitsPerSample == bitsPerSrcPixel) {
474:         // Fast path: bits per sample matches source pixel size
475:         loop(process_word);
476:       } else {
477:         // Slow path: bits per sample does not match source pixel size
478:         loop(process_bits);
479:       }
480:     }
481: 
482:     void invertColors() {
483:       uint8_t* data = image_.dataPtr<uint8_t>();
484:       for (size_t i = 0; i < image_.data.size(); ++i) {
485:         data[i] = ~data[i];
486:       }
487:     }
488:   };
