591:       const TiffImage::IFD& ifd,
592:       TiffImage::ImageData imageData) override
593:     {
594:       const int samplesPerPixel = requireSamplesPerPixel(ifd, 3);
595:       const int photometricInterpretation = requirePhotometricInterpretation(ifd, 2);
596:       const int compression = requireCompression(ifd, 1);
