601:         });
602:       const bool isPlanar = (planarConfiguration == 2);
603: 
604:       const auto bitsPerSampleVec = getIntVec(ifd, Tag::BitsPerSample);
605:       if (bitsPerSampleVec.size() != 3) {
606:         throw std::runtime_error("Expected 3 bits per sample for RGB image");
607:       }
608: 
609:       const int bitsPerSample = bitsPerSampleVec.front();
610:       for (auto bits : bitsPerSampleVec) {
611:         if (bits != bitsPerSample) {
612:           throw std::runtime_error("Unsupported bits per sample for RGB image");
613:         }
614:       }
615: 
616:       constexpr size_t maxDstValue = std::numeric_limits<DstType>::max();
617:       const size_t maxSrcValue = bitsPerSample < sizeof(size_t) * 8
618:         ? (size_t(1) << bitsPerSample) - 1 : std::numeric_limits<size_t>::max();
619: 
620:       const auto rectInfo = getRectInfo(ifd);
621: 
622:       // create the image and copy the pixel data
623:       image_ = Image::make<DstType, 3>(getWidth(ifd), getHeight(ifd), isPlanar);
624:       using UnaryOp = std::function<DstType(DstType)>;
625:       copyRectangles<SrcType,DstType,UnaryOp>(
626:         imageData, // source pixel data
627:         rectInfo,  // rectangle info
628:         isPlanar ? 1 : samplesPerPixel, // source image channels
629:         isPlanar ? samplesPerPixel : 1, // source image planes
630:         header.equalsHostByteOrder(),   // source data byte order
631:         [&](DstType value) -> DstType {
632:           return (value * maxDstValue) / maxSrcValue;
633:         }
634:       );
635:     }
636:   };
