638:   // TiffExporter implementation for all supported image types ---------------
639:   class TiffExporterAny : public TiffExporter
640:   {
641:     bool exported_ = false;
642:   public:
643:     // Callback for TiffCraft::load() function
644:     void operator()(
645:       const TiffImage::Header& header,
646:       const TiffImage::IFD& ifd,
647:       TiffImage::ImageData imageData) override
648:     {
649:       const int photometricInterpretation = getInt(ifd, Tag::PhotometricInterpretation, 1);
650: 
651:       if (photometricInterpretation >= 0 && photometricInterpretation <= 1) {
652:         // grayscale image types
653:         const int bitsPerSample = getInt(ifd, Tag::BitsPerSample, 1);
654:         if (bitsPerSample <= 8) {
655:           tryToExport<TiffExporterGray<uint8_t>>(header, ifd, imageData);
656:         } else if (bitsPerSample <= 15) {
657:           tryToExport<TiffExporterGray<uint16_t,uint8_t>>(header, ifd, imageData);
658:         } else if (bitsPerSample == 16) {
659:           tryToExport<TiffExporterGray<uint16_t>>(header, ifd, imageData);
660:         } else if (bitsPerSample <= 31) {
661:           tryToExport<TiffExporterGray<uint32_t,uint8_t>>(header, ifd, imageData);
662:         } else if (bitsPerSample == 32) {
663:           tryToExport<TiffExporterGray<uint32_t>>(header, ifd, imageData);
664:         }
665:       } else if (photometricInterpretation == 2) {
666:         // RGB image types
667:         std::vector<int> bitsPerSampleVec = getIntVec(ifd, Tag::BitsPerSample);
668:         if (bitsPerSampleVec.size() > 0
669:           && std::any_of(bitsPerSampleVec.begin(), bitsPerSampleVec.end(),
670:             [&](int n) { return n != bitsPerSampleVec.front(); })) {
671:           throw std::runtime_error("Unsupported bits per sample for RGB image");
672:         }
673:         const int bitsPerSample = bitsPerSampleVec.empty() ? 1 : bitsPerSampleVec.front();
674:         if (bitsPerSample <= 8) {
675:           tryToExport<TiffExporterRgb<uint8_t>>(header, ifd, imageData);
676:         } else if (bitsPerSample <= 15) {
677:           tryToExport<TiffExporterRgb<uint16_t,uint8_t>>(header, ifd, imageData);
678:         } else if (bitsPerSample == 16) {
679:           tryToExport<TiffExporterRgb<uint16_t>>(header, ifd, imageData);
680:         } else if (bitsPerSample <= 31) {
681:           tryToExport<TiffExporterRgb<uint32_t,uint8_t>>(header, ifd, imageData);
682:         } else if (bitsPerSample == 32) {
683:           tryToExport<TiffExporterRgb<uint32_t>>(header, ifd, imageData);
684:         }
685:       } else if (photometricInterpretation == 3) {
686:         // palette-color image types
687:         const int bitsPerSample = getInt(ifd, Tag::BitsPerSample, 1);
688:         if (bitsPerSample <= 8) {
689:           tryToExport<TiffExporterPalette<uint8_t>>(header, ifd, imageData);
690:         } else if (bitsPerSample <= 16) {
691:           tryToExport<TiffExporterPalette<uint16_t>>(header, ifd, imageData);
692:         }
693:       }
694: 
695:       if (!exported_ || image_.dataSize() == 0)
696:       { // image was not exported
697:         throw FormatNotSupportedError("No exporter can handle this image");
698:       }
699:     }
700: 
701:     template <typename Exporter>
702:     void tryToExport(const TiffImage::Header& header,
703:                      const TiffImage::IFD& ifd,
704:                      TiffImage::ImageData imageData)
705:     {
706:       if (!exported_) {
707:         // Image has not been exported yet
708:         try {
709:           // Try with the provided exporter
710:           Exporter exporter;
711:           exporter(header, ifd, imageData);
712:           image_ = exporter.takeImage();
713:           exported_ = true;
714:         } catch (const FormatNotSupportedError&) {
715:           // Image format not supported by the current exporter, ignore
716:         }
717:       }
718:     }
719:   };
720: }

