inline std::istream& readAt(
  std::istream& stream, std::streampos pos,
  std::byte* buffer, std::size_t size) {
  if (!stream) {
    throw std::runtime_error("Stream is not valid for reading");
  }
  struct SeekGuard {
    std::istream& stream;
    std::streampos oldPos;
    SeekGuard(std::istream& s, std::streampos p) : stream(s), oldPos(s.tellg()) {
      stream.seekg(p);
    }
    ~SeekGuard() {
      stream.seekg(oldPos);
    }
  } seekGuard(stream, pos);
  if (!stream) {
    throw std::runtime_error("Failed to seek to position in stream");
  }
  stream.read(reinterpret_cast<char*>(buffer), size);
  if (!stream || stream.gcount() != static_cast<std::streamsize>(size)) {
    throw std::runtime_error("Short read: expected " + std::to_string(size) + " bytes, got " + std::to_string(stream.gcount()));
  }
  return stream;
}

